const patterns={chained:{flow:["Audio in","Speech to text","Text model","Text to speech","Audio out"],best:"Learning each stage and inspecting transcripts.",tradeoff:"More stages add delay and more failure points.",view:"Start here if you want to see each component."},native:{flow:["Audio in","Speech-to-speech model","Audio out"],best:"Natural timing, tone, and interruption handling.",tradeoff:"The internal speech process is less visible.",view:"Use this after you understand the event timeline."}};
const metrics={outcome:{index:"01 / OUTCOME",title:"Did the agent complete the task?",summary:"A natural voice does not prove that the agent worked. Check the final application state and the result that the agent reported.",items:[["Task completion","Successful tasks ÷ attempted tasks"],["Final-state accuracy","The application contains the intended result"],["Tool accuracy","Correct tool, arguments, and execution order"],["Turns to completion","Conversation turns required for a successful task"]],color:"#6689d8"},speed:{index:"02 / SPEED",title:"How long did each stage take?",summary:"Measure the delay that the user hears. Then split that delay into endpointing, model, tool, synthesis, network, and playback time.",items:[["Perceived response latency","End of user speech to first played agent audio"],["Endpointing delay","End of speech to committed user turn"],["Tool latency","Tool start to useful tool result"],["P50 and P95","Normal delay and slow-tail delay"]],color:"#9275cf"},understanding:{index:"03 / UNDERSTANDING",title:"Did the agent understand the user?",summary:"A low transcription error rate can still hide a wrong name, number, or intent. Test the fields that affect the task.",items:[["Word error rate","Incorrect transcript words compared with a reference"],["Entity accuracy","Correct names, numbers, dates, and addresses"],["Intent accuracy","Correct interpretation of the requested action"],["Clarification rate","Turns where the agent must ask again"]],color:"#cf944b"},conversation:{index:"04 / CONVERSATION",title:"Did the conversation flow correctly?",summary:"Measure turn timing and interruption behavior. Review audio because a transcript cannot show all timing problems.",items:[["Response rate","User turns that receive a valid response"],["Unwanted interruption","Agent starts while the user still intends to speak"],["Barge-in stop time","Delay before agent audio stops after user speech"],["Unwanted silence","Long gaps with no useful audio or status"]],color:"#4f9c80"},reliability:{index:"05 / RELIABILITY",title:"Does the system recover from failure?",summary:"Track complete sessions and each stage that can fail. A fast agent is not useful when sessions drop or tools fail silently.",items:[["Session start success","Sessions that connect and become ready"],["No-response rate","User turns with no valid agent response"],["Drop and reconnect rate","Sessions that lose the transport"],["Tool recovery rate","Failed tool calls that end in a safe result"]],color:"#c96159"},cost:{index:"06 / COST + SAFETY",title:"Is each successful task safe and affordable?",summary:"Connect usage and safety checks to the outcome. Cost per minute alone can reward short failed sessions.",items:[["Cost per successful task","Total session cost ÷ successful tasks"],["Audio and token usage","Input and output use by session"],["Unauthorized action rate","Actions without required user approval"],["Sensitive-data exposure","Runs that reveal or retain restricted data"]],color:"#6f746f"}};

const patternButtons=[...document.querySelectorAll(".pattern-button")];
const patternFlow=document.querySelector("#pattern-flow");
function showPattern(name){const item=patterns[name];patternButtons.forEach(button=>{const active=button.dataset.pattern===name;button.classList.toggle("is-active",active);button.setAttribute("aria-selected",String(active))});patternFlow.replaceChildren(...item.flow.flatMap((label,index)=>{const node=document.createElement("span");node.textContent=label;if(index===item.flow.length-1)return[node];const arrow=document.createElement("i");arrow.textContent="→";return[node,arrow]}));document.querySelector("#pattern-best").textContent=item.best;document.querySelector("#pattern-tradeoff").textContent=item.tradeoff;document.querySelector("#pattern-view").textContent=item.view}
patternButtons.forEach(button=>button.addEventListener("click",()=>showPattern(button.dataset.pattern)));

const metricTabs=[...document.querySelectorAll(".metric-tab")];
const metricList=document.querySelector("#metric-list");
function showMetric(name){const item=metrics[name];metricTabs.forEach(tab=>{const active=tab.dataset.metric===name;tab.classList.toggle("is-active",active);tab.setAttribute("aria-selected",String(active));tab.tabIndex=active?0:-1});const index=document.querySelector("#metric-index");index.textContent=item.index;index.style.color=item.color;document.querySelector("#metric-title").textContent=item.title;document.querySelector("#metric-summary").textContent=item.summary;metricList.replaceChildren(...item.items.map(([term,description])=>{const row=document.createElement("div");const dt=document.createElement("dt");const dd=document.createElement("dd");dt.textContent=term;dd.textContent=description;row.append(dt,dd);return row}))}
metricTabs.forEach((tab,index)=>{tab.addEventListener("click",()=>showMetric(tab.dataset.metric));tab.addEventListener("keydown",event=>{if(!["ArrowUp","ArrowDown","ArrowLeft","ArrowRight"].includes(event.key))return;event.preventDefault();const forward=["ArrowDown","ArrowRight"].includes(event.key);const next=metricTabs[(index+(forward?1:-1)+metricTabs.length)%metricTabs.length];showMetric(next.dataset.metric);next.focus()})});

const revealTargets=document.querySelectorAll(".section-head,.architecture,.patterns,.formula-board,.metric-layout,.starter-scorecard,.test-stages,.build-grid,.sources");
if("IntersectionObserver" in window&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){revealTargets.forEach(target=>target.classList.add("reveal"));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;entry.target.classList.add("is-visible");observer.unobserve(entry.target)}),{threshold:.06});revealTargets.forEach(target=>observer.observe(target))}
